 "content": "from collections import Counter

# The dominant nonzero foreground color selects the learned 3x3 glyph.
GLYPHS = {
    1: [[0, 0, 8], [8, 8, 0], [0, 8, 0]],
    2: [[0, 0, 0], [8, 8, 8], [0, 0, 0]],
    3: [[0, 8, 8], [0, 8, 0], [0, 8, 0]],
}

def transform(grid):
    counts = Counter(x for row in grid for x in row if x != 0)
    color = counts.most_common(1)[0][0]
    return [row[:] for row in GLYPHS[color]]
